import { useState } from 'react';
import { Button, Code, Fieldset, Group, Stack, Text } from '@mantine/core';
import { useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { ErrorSummary } from './ErrorSummary';
import { EventFields } from './EventFields';
import { ExceptionsField } from './ExceptionsField';
import { OccurrencePreview } from './OccurrencePreview';
import { formatOccurrence, toPayload } from './payload';
import { getOccurrences, getRule } from './recurrence';
import { RepeatFields } from './RepeatFields';
import { SeriesEndFields } from './SeriesEndFields';
import type { RecurringEventPayload, RecurringEventValues } from './types';
import { useDependentFields } from './useDependentFields';
import { getInitialValues, recurringEventRules } from './validation';

function getFirstOccurrence(values: RecurringEventValues) {
  const rule = getRule(values);
  const [first] = rule
    ? getOccurrences(rule, {
        exceptions: rule.repeat === 'none' ? [] : values.exceptions,
        limit: 1,
      })
    : [];
  return first ? formatOccurrence(first, values.start ?? '', values.allDay) : 'No occurrences';
}

interface RecurringEventFormProps {
  onSubmit?: (payload: RecurringEventPayload) => void;
}

export function RecurringEventForm({ onSubmit }: RecurringEventFormProps) {
  const [submitted, setSubmitted] = useState<RecurringEventPayload | null>(null);
  const [showSummary, setShowSummary] = useState(false);

  const form = useForm<RecurringEventValues, RecurringEventPayload>({
    name: 'recurring-event',
    initialValues: getInitialValues(),
    validate: recurringEventRules,
    transformValues: toPayload,
  });

  useDependentFields(form);
  const repeat = form.useWatchValue('repeat');

  // Radio and checkbox groups and the masked date inputs put data-path on a wrapper
  const focusField = (path: string) => {
    const node = form.getInputNode(path);
    (node?.querySelector('input') ?? node)?.focus();
  };

  const handleSubmit = (payload: RecurringEventPayload) => {
    setShowSummary(false);
    setSubmitted(payload);
    notifications.show({
      title: 'Event created',
      message: `${payload.title} · ${getFirstOccurrence(form.getValues())}`,
    });
    onSubmit?.(payload);
  };

  const handleErrors = (errors: FormErrors) => {
    setShowSummary(true);
    focusField(Object.keys(errors)[0]);
  };

  return (
    <Stack gap="xl">
      <form onSubmit={form.onSubmit(handleSubmit, handleErrors)} noValidate>
        <Stack>
          {showSummary && <ErrorSummary form={form} onFocusField={focusField} />}

          <Fieldset legend="Event" radius="md">
            <EventFields form={form} />
          </Fieldset>

          <Fieldset legend="Recurrence" radius="md">
            <Stack>
              <RepeatFields form={form} />
              {repeat !== 'none' && <SeriesEndFields form={form} />}
              {repeat !== 'none' && <ExceptionsField form={form} />}
              <OccurrencePreview form={form} />
            </Stack>
          </Fieldset>

          <Group justify="flex-end">
            <Button type="submit">Create event</Button>
          </Group>
        </Stack>
      </form>

      {submitted && (
        <div>
          <Text size="sm" fw={500} mb={4}>
            Submitted event
          </Text>
          <Code block aria-label="Submitted event">
            {JSON.stringify(submitted, null, 2)}
          </Code>
        </div>
      )}
    </Stack>
  );
}

import { Alert, Anchor, Stack } from '@mantine/core';
import type { RecurringEventFormType } from './types';

interface ErrorSummaryProps {
  form: RecurringEventFormType;
  onFocusField: (path: string) => void;
}

export function ErrorSummary({ form, onFocusField }: ErrorSummaryProps) {
  const entries = Object.entries(form.errors);

  if (entries.length === 0) {
    return null;
  }

  return (
    <Alert color="red" variant="default" title="There is a problem">
      <Stack gap={4}>
        {entries.map(([path, message]) => (
          <Anchor
            key={path}
            component="button"
            type="button"
            size="sm"
            onClick={() => onFocusField(path)}
          >
            {message}
          </Anchor>
        ))}
      </Stack>
    </Alert>
  );
}

import { MaskedDateInput } from '@mantine/dates';
import type { RecurringEventFormType } from './types';
import { DEFAULT_END_TIME, DEFAULT_START_TIME } from './validation';

interface EventDateInputProps {
  form: RecurringEventFormType;
  path: 'start' | 'end';
  label: string;
  allDay: boolean;
}

/** Names of the parts of a MaskedDateInput for screen readers: "Start day", "Start hours" */
export function getDateFieldLabels(label: string) {
  return {
    dayInputLabel: `${label} day`,
    monthInputLabel: `${label} month`,
    yearInputLabel: `${label} year`,
    hoursInputLabel: `${label} hours`,
    minutesInputLabel: `${label} minutes`,
  };
}

export function EventDateInput({ form, path, label, allDay }: EventDateInputProps) {
  const inputProps = form.getInputProps(path);
  const fieldLabels = getDateFieldLabels(label);

  if (!allDay) {
    return (
      <MaskedDateInput
        key="date-time"
        label={label}
        withTime
        withAsterisk
        {...fieldLabels}
        {...inputProps}
      />
    );
  }

  const value: string | null = inputProps.value;
  const time = value?.slice(11) || (path === 'start' ? DEFAULT_START_TIME : DEFAULT_END_TIME);

  // The value keeps its time while only the date is shown, so turning All day off restores it
  return (
    <MaskedDateInput
      key="date"
      label={label}
      withAsterisk
      {...fieldLabels}
      {...inputProps}
      value={value ? value.slice(0, 10) : null}
      onChange={(date) => inputProps.onChange(date ? `${date} ${time}` : null)}
    />
  );
}

import { Select, SimpleGrid, Stack, Switch, Textarea, TextInput } from '@mantine/core';
import { EventDateInput } from './EventDateInput';
import type { RecurringEventFormType } from './types';
