    await chooseRepeat(user, 'Weekly');
    await skipDate(user, '28 October 2026');
    await user.click(screen.getByRole('button', { name: /Exceptions/ }));
    expect(await screen.findByRole('button', { name: '28 October 2026' })).toBeDisabled();
  });

